import fcntl
import os
import re
import sys
import time
import zipfile
from contextlib import contextmanager
from subprocess import run

from openlibrary.coverstore import config, db

SIZES = ('', 's', 'm', 'l')


def _size(size):
    size = size.lower()
    if size not in SIZES:
        raise ValueError('size must be one of empty, s, m, l')
    return size


class Cover:
    def __init__(self, attributes):
        self.attributes = attributes
        self.id = int(attributes['id'])

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        number = int(cover_id)
        if not 0 <= number < 10_000_000_000:
            raise ValueError('cover ID must fit in ten digits')
        padded = f'{number:010d}'
        return padded[:4], padded[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        size = _size(size)
        if protocol not in ('http', 'https'):
            raise ValueError('protocol must be http or https')
        if not re.fullmatch(r'[a-zA-Z0-9]+', ext):
            raise ValueError('invalid extension')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        name = f'{prefix}covers_{item_id}_{batch_id}.zip'
        suffix = f'-{size.upper()}' if size else ''
        filename = f'{int(cover_id):010d}{suffix}.{ext}'
        return f'{protocol}://archive.org/download/{item}/{name}/{filename}'

    def files(self):
        for size in SIZES:
            field = 'filename' + (f'_{size}' if size else '')
            filename = self.attributes.get(field)
            yield size, os.path.join(config.data_root, 'localdisk', filename) if filename else None

    def has_files(self):
        return all(path and os.path.isfile(path) for _, path in self.files())

    def delete_files(self):
        for _, path in self.files():
            if path and os.path.exists(path):
                os.remove(path)


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = _size(size) if size is not None else None

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item, batch = int(item_id), int(batch_id)
        if not 0 <= item <= 9999 or not 0 <= batch <= 99:
            raise ValueError('item or batch ID out of range')
        return f'{item:04d}', f'{batch:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls._norm_ids(item_id, batch_id)
        size = _size(size)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @property
    def start_id(self):
        return int(self.item_id) * 1_000_000 + int(self.batch_id) * 10_000

    @contextmanager
    def lock(self):
        \"\"\"Serialize writers and finalizers for all sizes in this batch.\"\"\"
        path = self.get_abspath(self.item_id, self.batch_id, ext='lock')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'a+b') as handle:
            fcntl.flock(handle, fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(handle, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=True, uploader=None):
        uploader = uploader or Uploader()
        with self.lock():
            sizes = SIZES if self.size is None else (self.size,)
            paths = {size: self.get_abspath(self.item_id, self.batch_id, size) for size in sizes}
            if not all(os.path.isfile(path) for path in paths.values()):
                return False
            for size, path in paths.items():
                item = f'{size + \"_\" if size else \"\"}covers_{self.item_id}'
                if upload and not test and not uploader.is_uploaded(item, os.path.basename(path)):
                    uploader.upload(item, [path])
                if not uploader.is_uploaded(item, os.path.basename(path)):
                    return False
            if finalize and not test:
                if self.size is not None:
                    raise ValueError('finalization requires verification of all sizes')
                self._finalize_locked()
            return True

    def _finalize_locked(self):
        records = CoverDB().update_completed_batch(self.item_id, self.batch_id)
        for record in records:
            Cover(record).delete_files()
        for size in SIZES:
            os.remove(self.get_abspath(self.item_id, self.batch_id, size))

    def finalize(self, start_id=None, test=True):
        if start_id is not None and int(start_id) "'!= self.start_id:
            raise ValueError('"'start ID does not match batch')
        return self.process_pending(finalize=True, test=test)


class ZipManager:
    def __init__(self):
        self.zips = {}
        self.names = {}

    def add_file(self, name, filepath, mtime):
        match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.([a-zA-Z0-9]+)', name)
        if not match:
            raise ValueError(f'invalid cover filename: {name}')
        item_id, batch_id = Cover.id_to_item_and_batch_id(match.group(1))
        size = (match.group(2) or '').lower()
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zips:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zips[path] = archive
            self.names[path] = set(archive.namelist())
        if name not in self.names[path]:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, self.zips[path].open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            self.names[path].add(name)
        return path

    def close(self):
        for archive in self.zips.values():
            archive.close()
        self.zips.clear()
        self.names.clear()


class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths], check=True, capture_output=True, text=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(['ia', 'list', item], check=True, capture_output=True, text=True)
        found = any(line.strip().split('/')[-1] == zip_filename for line in result.stdout.splitlines())
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // 10_000 + 1) * 10_000 - 1

    def get_unarchived(self, limit=10_000):
        return self.db.select('cover', where='archived="'$f AND failed=$f AND id>=8000000'"',
                              vars={'f': False}, order='id', limit=limit)

    def get_batch(self, item_id, batch_id):
        batch = Batch(item_id, batch_id)
        return list(self.db.select('cover', where='id >= "'$start AND id <= $end AND archived=$t AND failed=$f'"',
                                   vars={'start': batch.start_id, 'end': self._get_batch_end_id(batch.start_id),
                                         't': True, 'f': False}, order='id'))

    def update_completed_batch(self, item_id, batch_id, ext='jpg'):
        records = self.get_batch(item_id, batch_id)
        transaction = self.db.transaction()
        try:
            for row in records:
                values = {'uploaded': True}
                for size in SIZES:
                    field = 'filename' + (f'_{size}' if size else '')
                    values[field] = Cover.get_cover_url(row.id, size, ext)
                self.db.update('cover', where='id="'$id AND archived=$t AND failed=$f'"',
                               vars={'id': row.id, 't': True, 'f': False}, **values)
            transaction.commit()
        except Exception:
            transaction.rollback()
            raise
        return records


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith('.jpg') for name in archive.namelist())


def open_zipfile(name):
    match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.[a-zA-Z0-9]+', name)
    if not match:
        raise ValueError(f'invalid cover filename: {name}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match.group(1))
    path = Batch.get_abspath(item_id, batch_id, (match.group(2) or '').lower())
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)


def get_zipfile(name):
    return open_zipfile(name)


def audit(group_id, chunk_ids=(0, 100), sizes=SIZES):
    scope = range(*(chunk_ids if isinstance(chunk_ids, tuple) else (0, chunk_ids)))
    for size in sizes:
